export const compressionToolLocales = Object.fromEntries(Object.keys(copies).map((language) => {
  const ui = Object.fromEntries(uiKeys.map((key, index) => [key, translations[language][index]]));
  if (translations[language].length !== uiKeys.length) throw new Error(`Compression UI translation count mismatch: ${language}`);
  return [language, { ui, copy: copies[language] }];
}));

